  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) return null;
  return createClient(url, key, {
    // No session, no refresh, no storage: this client is never a user.
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

type Row = { lat: number; lon: number; day: string; payload: CachedDay; fetched_at: string };

/**
 * ⚠️ Every method degrades to "no cache" rather than throwing.
 *
 * A cache that can take the app down is worse than no cache. If Supabase is
 * unreachable, a read returns empty (so the caller fetches live) and a write is
 * dropped (so the next request fetches again). Both are slow, neither is broken.
 */
export function postgresStore(): CacheStore {
  return {
    async read(lat, lon, dates) {
      const out = new Map<string, { payload: CachedDay; fetchedAt: Date }>();
      const db = serviceClient();
      if (!db || dates.length === 0) return out;

      const { data, error } = await db
        .from("weather_cache")
        .select("lat, lon, day, payload, fetched_at")
        .eq("lat", lat)
        .eq("lon", lon)
        .in("day", dates);

      if (error || !data) return out;
      for (const row of data as Row[]) {
        out.set(row.day, { payload: row.payload, fetchedAt: new Date(row.fetched_at) });
      }
      return out;
    },

    async write(entries) {
      const db = serviceClient();
      if (!db || entries.length === 0) return;

      /**
       * ⚠️ `ignoreDuplicates` IS the `on conflict do nothing`. A city waking up
       * at 08:00 is the concurrent case: two requests miss, both fetch, both
       * write. The loser must be a no-op, not an error — and definitely not an
       * overwrite, because the rows are equivalent anyway.
       *
       * ⚠️ It also means a STALE row is not replaced by this path. Staleness is
       * handled by `WEATHER_MAX_AGE_H` on read, which deletes-then-inserts
       * below rather than relying on upsert semantics.
       */
      const rows = entries.map((e) => ({
        lat: e.lat,
        lon: e.lon,
        day: e.day,
        payload: e.payload,
        fetched_at: e.fetchedAt.toISOString(),
      }));

      // Refreshing a stale row is a replace, so clear the keys we are about to
      // write. Scoped to one place and the exact days in hand.
      await db
        .from("weather_cache")
        .delete()
        .eq("lat", entries[0].lat)
        .eq("lon", entries[0].lon)
        .in("day", entries.map((e) => e.day));

      await db.from("weather_cache").insert(rows);
    },
  };
}

